// Separate keys into Multi-word phrases and Single-word tokens
const MULTI_WORD_KEYS = Object.keys(MASTER_TRANSLATION_DICT)
    .filter(k => k.includes(' '))
    .sort((a, b) => b.length - a.length);

const SINGLE_WORD_KEYS = Object.keys(MASTER_TRANSLATION_DICT)
    .filter(k => !k.includes(' ') && k.length >= 3)
    .sort((a, b) => b.length - a.length);

// Inverted dictionary for EN -> AR
const REVERSE_TRANSLATION_DICT = {};
for (const [arK, enV] of Object.entries(MASTER_TRANSLATION_DICT)) {
    if (arK && enV && typeof enV === 'string') {
        REVERSE_TRANSLATION_DICT[enV.trim().toLowerCase()] = arK.trim();
    }
}

const REVERSE_MULTI_WORD_KEYS = Object.keys(REVERSE_TRANSLATION_DICT)
    .filter(k => k.includes(' '))
    .sort((a, b) => b.length - a.length);

const REVERSE_SINGLE_WORD_KEYS = Object.keys(REVERSE_TRANSLATION_DICT)
    .filter(k => !k.includes(' ') && k.length >= 3)
    .sort((a, b) => b.length - a.length);

function escapeRegex(s) {
    return s.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
}

function translateStr(str, targetLang) {
    if (!str || typeof str !== 'string') return str;
    const trimmed = str.trim();
    if (!trimmed) return str;
    if (trimmed.startsWith('http://') || trimmed.startsWith('https://') || /^[0-9]+$/.test(trimmed)) return str;
    const isEn = (targetLang === 'en' || (!targetLang && (window.currentLang === 'en' || document.documentElement.lang === 'en')));

    if (isEn) {
        // AR -> EN
        if (trimmed === 'و') return 'and';
        if (MASTER_TRANSLATION_DICT[trimmed]) {
            return str.replace(trimmed, MASTER_TRANSLATION_DICT[trimmed]);
        }
        const normKey = trimmed.replace(/\s+/g, ' ');
        if (MASTER_TRANSLATION_DICT[normKey]) {
            return str.replace(trimmed, MASTER_TRANSLATION_DICT[normKey]);
        }
        const cleanNorm = normKey.replace(/[:\-\.\s]+$/, '');
        if (MASTER_TRANSLATION_DICT[cleanNorm]) {
            const diff = normKey.slice(cleanNorm.length);
            return str.replace(trimmed, MASTER_TRANSLATION_DICT[cleanNorm] + diff);
        }
        const cleanKey = trimmed.replace(/[:\-\.\s]+$/, '');
        if (MASTER_TRANSLATION_DICT[cleanKey]) {
            const diff = trimmed.slice(cleanKey.length);
            return str.replace(trimmed, MASTER_TRANSLATION_DICT[cleanKey] + diff);
        }
        let replaced = str;
        for (let i = 0; i < MULTI_WORD_KEYS.length; i++) {
            const key = MULTI_WORD_KEYS[i];
            if (replaced.includes(key)) {
                replaced = replaced.split(key).join(MASTER_TRANSLATION_DICT[key]);
                if (!/[\u0600-\u06FF]/.test(replaced)) return replaced;
            }
        }
        for (let i = 0; i < SINGLE_WORD_KEYS.length; i++) {
            const key = SINGLE_WORD_KEYS[i];
            const reg = new RegExp('(?<![\\u0600-\\u06FF])' + escapeRegex(key) + '(?![\\u0600-\\u06FF])', 'g');
            if (reg.test(replaced)) {
                replaced = replaced.replace(reg, MASTER_TRANSLATION_DICT[key]);
                if (!/[\u0600-\u06FF]/.test(replaced)) return replaced;
            }
        }
        return replaced;
    } else {
        // EN -> AR
        const lower = trimmed.toLowerCase();
        if (REVERSE_TRANSLATION_DICT[lower]) {
            return str.replace(trimmed, REVERSE_TRANSLATION_DICT[lower]);
        }
        const cleanLower = lower.replace(/[:\-\.\s]+$/, '');
        if (REVERSE_TRANSLATION_DICT[cleanLower]) {
            const diff = trimmed.slice(cleanLower.length);
            return str.replace(trimmed, REVERSE_TRANSLATION_DICT[cleanLower] + diff);
        }
        let replaced = str;
        for (let i = 0; i < REVERSE_MULTI_WORD_KEYS.length; i++) {
            const key = REVERSE_MULTI_WORD_KEYS[i];
            const reg = new RegExp('\\b' + escapeRegex(key) + '\\b', 'gi');
            if (reg.test(replaced)) {
                replaced = replaced.replace(reg, REVERSE_TRANSLATION_DICT[key]);
            }
        }
        for (let i = 0; i < REVERSE_SINGLE_WORD_KEYS.length; i++) {
            const key = REVERSE_SINGLE_WORD_KEYS[i];
            const reg = new RegExp('\\b' + escapeRegex(key) + '\\b', 'gi');
            if (reg.test(replaced)) {
                replaced = replaced.replace(reg, REVERSE_TRANSLATION_DICT[key]);
            }
        }
        return replaced.replace(/\s*\([A-Za-z0-9\s\.\&\+\-\_\/]+\)/g, '');
    }
}

function translateAllDomNodes(targetLang) {
    const isEn = (targetLang === 'en' || (!targetLang && (window.currentLang === 'en' || document.documentElement.lang === 'en')));
    
    const walker = document.createTreeWalker(
        document.body,
        NodeFilter.SHOW_TEXT,
        {
            acceptNode: function(node) {
                const parent = node.parentElement;
                if (!parent) return NodeFilter.FILTER_REJECT;
                const tag = parent.tagName.toLowerCase();
                if (['script', 'style', 'code', 'pre'].includes(tag)) {
                    return NodeFilter.FILTER_REJECT;
                }
                if (parent.closest('.CodeMirror') || parent.closest('#editor') || parent.isContentEditable || parent.closest('.notranslate') || parent.closest('[data-no-translate]')) {
                    return NodeFilter.FILTER_REJECT;
                }
                const val = node.nodeValue.trim();
                if (!val || val.length === 0) return NodeFilter.FILTER_SKIP;
                if (isEn && !/[\u0600-\u06FF]/.test(val)) return NodeFilter.FILTER_SKIP;
                return NodeFilter.FILTER_ACCEPT;
            }
        }
    );

    const nodesToUpdate = [];
    while (walker.nextNode()) {
        nodesToUpdate.push(walker.currentNode);
    }

    for (const node of nodesToUpdate) {
        node.nodeValue = translateStr(node.nodeValue, isEn ? 'en' : 'ar');
    }

    document.querySelectorAll('select option').forEach(opt => {
        const txt = opt.textContent;
        const translated = translateStr(txt, isEn ? 'en' : 'ar');
        if (translated !== txt) {
            opt.textContent = translated;
        }
    });

    document.querySelectorAll('input[placeholder], textarea[placeholder]').forEach(inp => {
        const ph = inp.getAttribute('placeholder');
        if (ph) {
            const translatedPh = translateStr(ph, isEn ? 'en' : 'ar');
            if (translatedPh !== ph) {
                inp.setAttribute('placeholder', translatedPh);
            }
        }
    });

    document.querySelectorAll('[title]').forEach(el => {
        const title = el.getAttribute('title');
        if (title && isEn && /[\u0600-\u06FF]/.test(title)) {
            el.setAttribute('title', translateStr(title, 'en'));
        }
    });

    document.querySelectorAll('[aria-label]').forEach(el => {
        const aria = el.getAttribute('aria-label');
        if (aria && isEn && /[\u0600-\u06FF]/.test(aria)) {
            el.setAttribute('aria-label', translateStr(aria, 'en'));
        }
    });
}

function applyTranslations(lang) {
    window.currentLang = lang;
    if (!['ar', 'en'].includes(lang)) lang = 'ar';
    
    document.documentElement.lang = lang;
    document.documentElement.dir = lang === 'ar' ? 'rtl' : 'ltr';
    document.documentElement.setAttribute('dir', lang === 'ar' ? 'rtl' : 'ltr');
    document.body.dir = lang === 'ar' ? 'rtl' : 'ltr';
    document.body.setAttribute('dir', lang === 'ar' ? 'rtl' : 'ltr');
    localStorage.setItem('blogger_ui_lang', lang);

    // Update language toggle button label
    const langLabel = document.getElementById('topbar-lang-label');
    if (langLabel) {
        langLabel.textContent = lang === 'ar' ? 'English' : 'العربية';
    } else {
        const btn = document.getElementById('btn-toggle-lang');
        if (btn) btn.innerHTML = `<span class="lang-text" id="topbar-lang-label">${lang === 'ar' ? 'English' : 'العربية'}</span><span class="lang-globe-icon">🌐</span>`;
    }

    // Update brand title & logo (preserve custom brand & uploaded logo)
    const brandTitleText = document.getElementById('brand-title-text');
    const studioNameInput = document.getElementById('studio-brand-name');
    if (brandTitleText && studioNameInput && studioNameInput.value) {
        brandTitleText.textContent = studioNameInput.value;
    } else if (brandTitleText && !brandTitleText.textContent) {
        brandTitleText.textContent = 'Blogor Studio';
    }
    const brandLogoIcon = document.querySelector('.brand-logo-icon');
    if (brandLogoIcon && !brandLogoIcon.querySelector('img')) {
        brandLogoIcon.textContent = 'B';
    }

    if (typeof updatePublishButtonLabel === "function") updatePublishButtonLabel();
    const dict = I18N[lang] || I18N['ar'];
    if (!dict) return;

    // Update document title
    if (dict['app_title']) {
        document.title = dict['app_title'];
    }

    // Apply to all elements with data-i18n (preserving child icons if present)
    document.querySelectorAll('[data-i18n]').forEach(el => {
        const key = el.getAttribute('data-i18n');
        if (key === 'btn_publish_now') {
            const isEditing = Boolean(window.currentEditingPostId || (typeof currentEditingPostId !== 'undefined' && currentEditingPostId));
            el.textContent = isEditing ? (lang === 'en' ? 'Update Post Now' : 'تحديث المنشور الآن') : (lang === 'en' ? 'Publish Now' : 'نشر الآن');
            return;
        }
        const val = dict[key];
        if (!val) return;
        if (el.tagName === 'INPUT' || el.tagName === 'TEXTAREA') {
            el.placeholder = val;
        } else {
            const span = el.querySelector('span:not(.badge):not(.btn-icon):not([class*="icon"])');
            const icon = el.querySelector('i');
            if (span) {
                span.textContent = val;
            } else if (icon) {
                const iconHtml = icon.outerHTML;
                el.innerHTML = `${iconHtml} <span>${val}</span>`;
            } else {
                el.textContent = val;
            }
        }
    });

    // Apply to all elements with data-i18n-ph
    document.querySelectorAll('[data-i18n-ph]').forEach(el => {
        const key = el.getAttribute('data-i18n-ph');
        if (dict[key]) el.placeholder = dict[key];
    });

    // Apply to all elements with data-i18n-title
    document.querySelectorAll('[data-i18n-title]').forEach(el => {
        const key = el.getAttribute('data-i18n-title');
        if (dict[key]) el.title = dict[key];
    });

    // Update active topbar title from active nav item
    const activeNavLabel = document.querySelector('.nav-item.active .nav-label');
    const topbarTitle = document.getElementById('topbar-title-text');
    if (activeNavLabel && topbarTitle) {
        topbarTitle.textContent = activeNavLabel.textContent;
    }

    // Refresh dynamic views if active
    if (typeof renderCategoriesGrid === 'function' && document.getElementById('tab-categories')?.classList.contains('active')) {
        renderCategoriesGrid();
    }
    if (typeof loadThemeSnapshotsList === 'function' && document.getElementById('modal-theme-restore')?.style.display === 'flex') {
        loadThemeSnapshotsList();
    }

    // Deep translate all DOM text nodes, select options, and placeholders
    try {
        if (typeof translateAllDomNodes === 'function') {
            translateAllDomNodes(lang);
        }
    } catch(err) {
        console.error('Error in translateAllDomNodes:', err);
    }
}

// Language Toggle for Dashboard UI
function setupLanguageToggle() {
    const savedLang = localStorage.getItem('blogger_ui_lang') || 'ar';
    applyTranslations(savedLang);
}

// Check OAuth callback parameters from URL
function checkUrlAuthParams() {
    const urlParams = new URLSearchParams(window.location.search);
    if (urlParams.get('auth_success')) {
        showToast('تم ربط حساب Google بنجاح وتم تنشيط واجهة Blogger API v3!', 'success');
        window.history.replaceState({}, document.title, window.location.pathname);
    }
    if (urlParams.get('auth_error')) {
        showToast(`فشل ربط حساب Google: ${urlParams.get('auth_error')}`, 'error');
        window.history.replaceState({}, document.title, window.location.pathname);
    }
}

// -------------------------------------------------------------
// DATA SYNCHRONIZATION
// -------------------------------------------------------------
async function syncAllData(forceRefresh = false) {
    const btn = document.getElementById('btn-sync-all');
    if (btn) btn.classList.add('loading');
    
    try {
        await Promise.all([
            loadDashboardStats(),
            loadPosts(forceRefresh),
            loadPages(),
            loadTranslations(),
            (typeof loadOAuthAccounts === 'function' ? loadOAuthAccounts() : Promise.resolve())
        ]);
        showToast('تمت مزامنة جميع البيانات مع المدونة بنجاح', 'success');
    } catch (e) {
        console.error('Sync error:', e);
    } finally {
        if (btn) btn.classList.remove('loading');
    }
}

// Load Stats & Diagnostics
async function loadDashboardStats() {
    if (typeof loadModernDashboardStats === 'function') loadModernDashboardStats();
    try {
        const res = await fetch('/api/stats');
        const data = await res.json();

        // Sync the View Site button with the current active blog URL
        if (window.currentActiveBlogUrl) {
            updateViewSiteButton(window.currentActiveBlogUrl);
        } else if (data.blog_url) {
            updateViewSiteButton(data.blog_url);
        }
        
        const setElText = (id, val) => { const el = document.getElementById(id); if (el) el.textContent = val; };
        setElText('stat-total-posts', data.total_posts || 0);
        setElText('stat-ar-posts', data.arabic_posts || 0);
        setElText('stat-en-posts', data.english_posts || 0);
        setElText('stat-trans-pairs', `${data.paired_translations || 0}/5`);
        setElText('stat-latency', `${data.latency_ms || 0} ms`);
        setElText('stat-conn-mode', data.connection_mode || 'Feed');
        setElText('stat-last-sync', data.last_sync || '');
        const badgePosts = document.getElementById('nav-badge-posts');
        if (badgePosts) badgePosts.textContent = data.total_posts || 0;
        const badgeTrans = document.getElementById('nav-badge-trans');
        if (badgeTrans) badgeTrans.textContent = `${data.paired_translations || 0}/5`;
    } catch (e) {
        console.error('Stats load error:', e);
    }
}

// -------------------------------------------------------------
// POSTS & TRASH MANAGEMENT SUITE
// -------------------------------------------------------------
let allTrashPosts = [];
let selectedTrashPostIds = new Set();
window.currentPostsSection = 'all';

async function loadTrashPosts(targetBlogId = null) {
    const activeId = targetBlogId || localStorage.getItem('studio_active_blog_id') || '';
    const canonicalId = (activeId === '5132150821033221945' ? '3715457895504629620' : (['2026102901', '202'].includes(activeId) ? '6735965676618679814' : (activeId || '3715457895504629620')));
    try {
        const res = await fetch(`/api/posts/trash?blog_id=${activeId}`);
        const data = await res.json();
        allTrashPosts = (data && data.posts) ? data.posts : (Array.isArray(data) ? data : []);
        const preseedStore = (typeof window !== 'undefined' && window.REAL_BLOG_PRESEEDED_TRASH) ? window.REAL_BLOG_PRESEEDED_TRASH : (typeof REAL_BLOG_PRESEEDED_TRASH !== 'undefined' ? REAL_BLOG_PRESEEDED_TRASH : null);
        if (!allTrashPosts.length && preseedStore) {
            const preseeded = preseedStore[canonicalId] || preseedStore['3715457895504629620'];
            if (preseeded && preseeded.length > 0) {
                allTrashPosts = JSON.parse(JSON.stringify(preseeded));
            }
        }
        const elTrash = document.getElementById('count-trash-posts');
        if (elTrash) elTrash.textContent = String(allTrashPosts.length);
        if (window.currentPostsSection === 'trash') {
            filterPosts();
        }
    } catch(e) {
        console.warn('loadTrashPosts fallback notice:', e);
        const preseedStore2 = (typeof window !== 'undefined' && window.REAL_BLOG_PRESEEDED_TRASH) ? window.REAL_BLOG_PRESEEDED_TRASH : (typeof REAL_BLOG_PRESEEDED_TRASH !== 'undefined' ? REAL_BLOG_PRESEEDED_TRASH : null);
        if (preseedStore2) {
            const preseeded = preseedStore2[canonicalId] || preseedStore2['3715457895504629620'];
            allTrashPosts = preseeded ? JSON.parse(JSON.stringify(preseeded)) : [];
        } else {
            allTrashPosts = [];
        }
        const elTrash = document.getElementById('count-trash-posts');
        if (elTrash) elTrash.textContent = String(allTrashPosts.length);
        if (window.currentPostsSection === 'trash') {
            filterPosts();
        }
    }
}
window.loadTrashPosts = loadTrashPosts;

async function loadPosts(forceRefresh = false) {
    const tbody = document.getElementById('posts-table-body');
    if (tbody) tbody.innerHTML = '<tr><td colspan="7" style="text-align:center;padding:24px;">جاري جلب المنشورات من بلوجر...</td></tr>';
    
    try {
        const activeId = localStorage.getItem('studio_active_blog_id') || '';
        const res = await fetch(`/api/posts?blog_id=${activeId}&refresh=${forceRefresh}`);
        allPosts = await res.json();
        if (!Array.isArray(allPosts)) allPosts = [];
        allPosts.forEach(p => {
            p.content = p.content_html || p.content || '';
            p.content_html = p.content_html || p.content || '';
        });
        window.allPosts = allPosts;
        
        // Populate Categories dropdown filter
        const catSelect = document.getElementById('posts-filter-cat');
        if (catSelect) {
            const currentCat = catSelect.value;
            const uniqueCats = new Set();
            allPosts.forEach(p => (p.labels || []).forEach(l => { if (!['ar','en'].includes(l)) uniqueCats.add(l); }));
            catSelect.innerHTML = '<option value="all">كل الأقسام</option>' + Array.from(uniqueCats).map(c => `<option value="${escapeHtml(c)}">${escapeHtml(c)}</option>`).join('');
            catSelect.value = currentCat;
        }

        // Populate article paired selector in Article Studio
        const pairSelect = document.getElementById('art-paired-post');
        if (pairSelect) {
            pairSelect.innerHTML = '<option value="">-- بدون ارتباط حالياً --</option>' + allPosts.map(p => `
                <option value="${p.id}">[${(p.language || p.lang) === 'ar' ? 'عربي' : 'EN'}] ${escapeHtml(p.title || 'بدون عنوان')}</option>
            `).join('');
        }

        // Parallel load trash posts
        await loadTrashPosts(activeId);

        filterPosts();
        updateSidebarPostCounters(allPosts);
        if (typeof renderModernOverviewTable === 'function') renderModernOverviewTable(allPosts);
        if (typeof populateOverviewCategoriesFilter === 'function') populateOverviewCategoriesFilter();
        if (typeof updateSidebarCounters === 'function') updateSidebarCounters(allPosts);

    } catch (e) {
        if (tbody) tbody.innerHTML = `<tr><td colspan="7" style="text-align:center;color:var(--accent-rose);padding:24px;">فشل جلب المقالات: ${e.message}</td></tr>`;
    }
}
window.loadPosts = loadPosts;

function renderPostsTable(posts, isTrash = false) {
    const tbody = document.getElementById('posts-table-body');
    if (!tbody) return;
    
    if (!posts.length) {
        const section = window.currentPostsSection || 'all';
        let emptyMsg = '<i class="fas fa-newspaper" style="font-size:24px;margin-bottom:8px;display:block;opacity:0.5;"></i>لا توجد مقالات مطابقة لمعايير البحث';
        if (isTrash || section === 'trash') {
            emptyMsg = '<i class="fas fa-trash" style="font-size:24px;margin-bottom:8px;display:block;opacity:0.5;"></i>سلة المحذوفات فارغة، لا توجد مقالات محذوفة 🗑️';
        } else if (section === 'scheduled') {
            emptyMsg = '<i class="fas fa-clock" style="font-size:24px;margin-bottom:8px;display:block;opacity:0.5;"></i>لا توجد مقالات مجدولة حالياً 🕒';
        } else if (section === 'draft') {
            emptyMsg = '<i class="fas fa-file-alt" style="font-size:24px;margin-bottom:8px;display:block;opacity:0.5;"></i>لا توجد مقالات في المسودات 📝';
        } else if (section === 'live') {
            emptyMsg = '<i class="fas fa-check-circle" style="font-size:24px;margin-bottom:8px;display:block;opacity:0.5;"></i>لا توجد مقالات منشورة حالياً 🟢';
        }
        tbody.innerHTML = `<tr><td colspan="7" style="text-align:center;padding:36px;color:var(--text-muted);">${emptyMsg}</td></tr>`;
        return;
    }

    tbody.innerHTML = posts.map(p => {
        const isChecked = isTrash ? selectedTrashPostIds.has(String(p.id)) : selectedPostIds.has(String(p.id));
        const postTitle = escapeHtml(p.title || 'بدون عنوان');
        let snippetRaw = p.snippet || '';
        if ((!snippetRaw || snippetRaw === 'undefined' || snippetRaw === 'null') && (p.content || p.content_html)) {
            snippetRaw = (p.content_html || p.content || '').replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim().slice(0, 120);
        }
        const snippetText = (snippetRaw && snippetRaw !== 'undefined' && snippetRaw !== 'null') ? escapeHtml(snippetRaw) : '';
        const postImg = p.image || p.image_url || 'https://images.unsplash.com/photo-1518770660439-4636190af475?w=200';
        const postLang = (p.language || p.lang || (/[؀-ۿ]/.test(p.title || '') ? 'ar' : 'en'));
        const langBadge = `<span class="badge ${postLang}">${postLang === 'ar' ? '🇸🇦 العربية' : '🇬🇧 English'}</span>`;
        
        const rawLabels = Array.isArray(p.labels) ? p.labels : (typeof p.labels_json === 'string' ? JSON.parse(p.labels_json || '[]') : []);
        const catLabels = rawLabels.filter(l => l && !['ar', 'en'].includes(l)).slice(0, 2);
        const catDisplay = catLabels.length 
            ? catLabels.map(l => `<span style="font-size:11px;background:var(--bg-soft);padding:3px 7px;border-radius:4px;margin-left:4px;">${escapeHtml(l)}</span>`).join('') 
            : '<span style="font-size:11px;color:var(--text-muted);">بدون تصنيف</span>';

        const pStatus = (p.status || (p.is_draft ? 'DRAFT' : (p.is_scheduled ? 'SCHEDULED' : 'LIVE'))).toUpperCase();
        const isLive = (pStatus === 'LIVE' && !p.is_draft && !p.is_scheduled);

        let statusBadge = '';
        if (isTrash) {
            statusBadge = `<span class="badge" style="background:rgba(239,68,68,0.18);color:#f87171;border:1px solid rgba(239,68,68,0.35);font-size:10px;">🗑️ محذوف</span>`;
        } else if (pStatus === 'DRAFT' || p.is_draft) {
            statusBadge = `<span class="badge" style="background:rgba(245,158,11,0.18);color:#f59e0b;border:1px solid rgba(245,158,11,0.35);font-size:10px;">📝 مسودة</span>`;
        } else if (pStatus === 'SCHEDULED' || p.is_scheduled) {
            statusBadge = `<span class="badge" style="background:rgba(59,130,246,0.18);color:#60a5fa;border:1px solid rgba(59,130,246,0.35);font-size:10px;">🕒 مجدول</span>`;
        } else {
            statusBadge = `<span class="badge en" style="font-size:10px;">🟢 منشور</span>`;
        }

        let rawDate = isTrash ? (p.deleted_at || p.display_date) : (p.display_date || p.published || p.published_at || p.updated || p.created_at);
        let formattedDate = 'غير متوفر';
        if (rawDate && rawDate !== 'undefined' && rawDate !== 'null') {
            formattedDate = String(rawDate).substring(0, 10);
            if ((pStatus === 'SCHEDULED' || isTrash) && String(rawDate).length > 10) {
                const timePart = String(rawDate).substring(11, 16);
                if (timePart) formattedDate += ` ${timePart}`;
            }
        } else if (pStatus === 'SCHEDULED') {
            formattedDate = 'موعد الجدولة غير محدد';
        } else if (isTrash) {
            formattedDate = 'تاريخ الحذف غير متوفر';
        } else {
            formattedDate = 'تاريخ النشر غير متوفر';
        }

        // Action Buttons
        let actionsHtml = '';
        if (isTrash) {
            actionsHtml = `
                <div style="display:flex;align-items:center;gap:6px;">
                    <button type="button" onclick="restorePost('${p.id}')" class="table-action-btn" title="استعادة المقال إلى المسودات" style="color:#10b981;border:1px solid rgba(16,185,129,0.35);background:rgba(16,185,129,0.12);padding:4px 9px;border-radius:6px;font-size:11.5px;font-weight:700;display:inline-flex;align-items:center;gap:4px;">
                        <i class="fas fa-undo"></i> <span>استعادة</span>
                    </button>
                    <button type="button" onclick="deletePermanentConfirm('${p.id}')" class="table-action-btn" title="حذف نهائي لا يمكن استعادته" style="color:#ef4444;border:1px solid rgba(239,68,68,0.35);background:rgba(239,68,68,0.12);padding:4px 9px;border-radius:6px;font-size:11.5px;font-weight:700;display:inline-flex;align-items:center;gap:4px;">
                        <i class="fas fa-trash-alt"></i> <span>حذف نهائي</span>
                    </button>
                </div>
            `;
        } else {
            const previewBtn = p.url 
                ? `<a href="${p.url}" target="_blank" class="table-action-btn btn-view" title="معاينة المقال على الموقع الحي (View Live)"><i class="fas fa-eye"></i></a>`
                : `<button type="button" onclick="previewPostModal('${p.id}')" class="table-action-btn btn-view" title="معاينة المقال"><i class="fas fa-eye"></i></button>`;

            const toggleDraftBtn = isLive 
                ? `<button type="button" onclick="togglePostDraftStatus('${p.id}', true)" class="table-action-btn btn-draft" title="تحويل سريع إلى مسودة (Revert to Draft)"><i class="fas fa-file-alt"></i></button>`
                : `<button type="button" onclick="togglePostDraftStatus('${p.id}', false)" class="table-action-btn btn-publish" title="نشر المقال فوراً على الموقع (Publish Live)"><i class="fas fa-paper-plane"></i></button>`;

            actionsHtml = `
                <div style="display:flex;align-items:center;gap:6px;">
                    ${previewBtn}
                    <button type="button" onclick="editPostInStudio('${p.id}')" class="table-action-btn btn-edit" title="تعديل المقال في الاستوديو"><i class="fas fa-edit"></i></button>
                    ${toggleDraftBtn}
                    <button type="button" onclick="createTranslationCounterpart('${p.id}')" class="table-action-btn btn-trans" title="إنشاء المقابل المترجم"><i class="fas fa-language"></i></button>
                    <button type="button" onclick="deletePostConfirm('${p.id}')" class="table-action-btn btn-delete" title="نقل إلى سلة المحذوفات"><i class="fas fa-trash-alt"></i></button>
                </div>
            `;
        }

        const checkboxHtml = isTrash 
            ? `<input type="checkbox" value="${p.id}" ${isChecked ? 'checked' : ''} onchange="toggleSelectTrashPost('${p.id}', this.checked)">`
            : `<input type="checkbox" value="${p.id}" ${isChecked ? 'checked' : ''} onchange="toggleSelectPost('${p.id}', this.checked)">`;

        return `
            <tr>
                <td style="text-align:center;">
                    ${checkboxHtml}
                </td>
                <td>
                    <div class="post-row-item">
                        <img class="post-thumb" src="${postImg}" alt="${postTitle}" onerror="this.src='https://images.unsplash.com/photo-1518770660439-4636190af475?w=200';" />
                        <div>
                            <span class="post-title-link" style="font-weight:700;">${postTitle}</span>
                            ${snippetText ? `<div style="font-size:11.5px;color:var(--text-muted);margin-top:2px;">${snippetText}</div>` : ''}
                        </div>
                    </div>
                </td>
                <td>
                    ${langBadge}
                </td>
                <td>
                    ${catDisplay}
                </td>
                <td>
                    ${statusBadge}
                </td>
                <td style="color:var(--text-muted);font-size:12px;white-space:nowrap;">${formattedDate}</td>
                <td>
                    ${actionsHtml}
                </td>
            </tr>
        `;
    }).join('');
}
window.renderPostsTable = renderPostsTable;

function handlePostsFilterStatusChange(newStatus) {
    const val = (newStatus || 'all').toUpperCase();
    if (val === 'TRASH') {
        navigateToPostsSection('trash');
    } else if (val === 'SCHEDULED') {
        navigateToPostsSection('scheduled');
    } else if (val === 'DRAFT') {
        navigateToPostsSection('draft');
    } else if (val === 'LIVE') {
        navigateToPostsSection('live');
    } else {
        navigateToPostsSection('all');
    }
}
window.handlePostsFilterStatusChange = handlePostsFilterStatusChange;

function filterPosts() {
    const search = (document.getElementById('posts-search-input')?.value || '').toLowerCase().trim();
    const lang = document.getElementById('posts-filter-lang')?.value || 'all';
    const cat = document.getElementById('posts-filter-cat')?.value || 'all';
    const statusVal = (document.getElementById('posts-filter-status')?.value || 'all').toUpperCase();
    const currentSection = window.currentPostsSection || 'all';

    // Synchronize effective status filter
    let statusFilter = statusVal;
    if (currentSection === 'draft' && statusVal === 'ALL') statusFilter = 'DRAFT';
    else if (currentSection === 'scheduled' && statusVal === 'ALL') statusFilter = 'SCHEDULED';
    else if (currentSection === 'live' && statusVal === 'ALL') statusFilter = 'LIVE';
    else if (currentSection === 'trash' && statusVal === 'ALL') statusFilter = 'TRASH';

    // Trash View
    if (currentSection === 'trash' || statusFilter === 'TRASH' || statusVal === 'TRASH') {
        const filtered = (allTrashPosts || []).filter(p => {
            const titleStr = (p.title || '').toLowerCase();
            const snippetStr = (p.snippet || '').toLowerCase();
            const matchesSearch = !search || titleStr.includes(search) || snippetStr.includes(search);
            const pLang = p.language || p.lang || (/[؀-ۿ]/.test(p.title || '') ? 'ar' : 'en');
            const matchesLang = (lang === 'all') || (pLang === lang);
            const pLabels = Array.isArray(p.labels) ? p.labels : (typeof p.labels_json === 'string' ? JSON.parse(p.labels_json || '[]') : []);
            const matchesCat = (cat === 'all') || pLabels.includes(cat);
            return matchesSearch && matchesLang && matchesCat;
        });
        renderPostsTable(filtered, true);
        return;
    }

    // Active Posts View (All, Draft, Scheduled, Live)
    const filtered = (allPosts || []).filter(p => {
        const titleStr = (p.title || '').toLowerCase();
        const snippetStr = (p.snippet || '').toLowerCase();
        const matchesSearch = !search || titleStr.includes(search) || snippetStr.includes(search);
        const pLang = p.language || p.lang || (/[؀-ۿ]/.test(p.title || '') ? 'ar' : 'en');
        const matchesLang = (lang === 'all') || (pLang === lang);
        const pLabels = Array.isArray(p.labels) ? p.labels : (typeof p.labels_json === 'string' ? JSON.parse(p.labels_json || '[]') : []);
        const matchesCat = (cat === 'all') || pLabels.includes(cat);

        const pStatus = (p.status || (p.is_draft ? 'DRAFT' : (p.is_scheduled ? 'SCHEDULED' : 'LIVE'))).toUpperCase();
        let matchesStatus = (statusFilter === 'ALL');
        if (statusFilter === 'DRAFT') {
            matchesStatus = (pStatus === 'DRAFT' || Boolean(p.is_draft));
        } else if (statusFilter === 'SCHEDULED') {
            matchesStatus = (pStatus === 'SCHEDULED' || Boolean(p.is_scheduled));
        } else if (statusFilter === 'LIVE') {
            matchesStatus = (pStatus === 'LIVE' && !p.is_draft && !p.is_scheduled);
        }
        return matchesSearch && matchesLang && matchesCat && matchesStatus;
    });

    renderPostsTable(filtered, false);
}
window.filterPosts = filterPosts;

// Normal Posts Selection & Bulk Actions
function toggleSelectAllPosts(masterCheckbox) {
    const isTrash = (window.currentPostsSection === 'trash');
    if (isTrash) {
        if (masterCheckbox.checked) {
            allTrashPosts.forEach(p => selectedTrashPostIds.add(String(p.id)));
        } else {
            selectedTrashPostIds.clear();
        }
        filterPosts();
        updateTrashBulkActionBar();
    } else {
        if (masterCheckbox.checked) {
            allPosts.forEach(p => selectedPostIds.add(String(p.id)));
        } else {
            selectedPostIds.clear();
        }
        filterPosts();
        if (typeof renderModernOverviewTable === 'function') renderModernOverviewTable(allPosts);
        if (typeof populateOverviewCategoriesFilter === 'function') populateOverviewCategoriesFilter();
        updateBulkActionBar();
    }
}
